import { readFileSync } from 'node:fs';
import { strict as assert } from 'node:assert';
import vm from 'node:vm';

const root = new URL('../', import.meta.url);
const read = path => readFileSync(new URL(path, root), 'utf8');

const dataCode = read('js/webcode-lessons.js');
const sandbox = { window: {} };
vm.createContext(sandbox);
vm.runInContext(dataCode, sandbox);

const lessons = sandbox.window.WEBCODE_LESSONS;
assert.equal(Array.isArray(lessons), true, 'lessons array exists');
assert.equal(lessons.length, 30, 'WebCode course includes thirty lessons');
assert.deepEqual(Array.from(lessons, l => l.id), Array.from({ length: 30 }, (_, i) => i + 1), 'lesson ids are sequential 1-30');
lessons.forEach(lessonItem => {
  assert.ok(lessonItem.durationMinutes >= 132, `lesson ${lessonItem.id} is framed as at least 132 minutes after the challenge-depth upgrade`);
  assert.ok(lessonItem.starter?.html?.includes('<main'), `lesson ${lessonItem.id} has starter HTML`);
  assert.ok(lessonItem.starter?.css?.includes('background'), `lesson ${lessonItem.id} has starter CSS`);
  assert.ok(lessonItem.starter?.js?.includes('function'), `lesson ${lessonItem.id} has starter JavaScript`);
  assert.ok(lessonItem.lessonFlow.length >= 7, `lesson ${lessonItem.id} has a full guide flow`);
  const minimumExercises = [6, 7, 8, 9].includes(lessonItem.id) ? 6 : [2, 4, 5].includes(lessonItem.id) ? 7 : 8;
  assert.ok(lessonItem.exercises.length >= minimumExercises, `lesson ${lessonItem.id} has enough exercises`);
  assert.ok(lessonItem.vocabulary.length >= 4, `lesson ${lessonItem.id} has vocabulary`);
});

const lesson = lessons[0];
assert.equal(lesson.durationMinutes, 170, 'lesson 1 is framed as 170 minutes after adding extra code-understanding exercises');
assert.ok(lesson.title.includes('עמוד אמיתי') && lesson.title.includes('Blockly'), 'lesson has concise real Blockly page-builder title');
assert.ok(lesson.starter.html.includes('<button onclick="sayHello()">'), 'starter has working button');
assert.ok(lesson.starter.css.includes('border-radius'), 'starter includes visible styling');
assert.ok(lesson.starter.js.includes('getElementById("message")'), 'starter JS targets message id');
assert.ok(lesson.exercises.length >= 8, 'lesson includes many exercises');
assert.ok(lesson.lessonFlow.length >= 7, 'lesson includes full 90-minute guide flow');
assert.ok(lesson.vocabulary.some(v => v[0] === 'HTML'), 'vocabulary includes HTML');
assert.ok(lesson.vocabulary.some(v => v[0] === 'CSS'), 'vocabulary includes CSS');
assert.ok(lesson.vocabulary.some(v => v[0] === 'JavaScript'), 'vocabulary includes JavaScript');
assert.equal(lesson.mode, 'Real Blockly page builder', 'lesson 1 uses a real Blockly page builder');
assert.equal(lesson.realBlocklyBuilder, true, 'lesson 1 enables real Blockly workspace');
assert.ok(lesson.exercises.some(ex => ex.prompt.includes('גררו')), 'lesson 1 exercises require dragging blocks');

const lesson2 = lessons[1];
assert.equal(lesson2.durationMinutes, 170, 'lesson 2 is framed as 170 minutes with deeper code practice');
assert.ok(lesson2.title.includes('סטודיו עיצוב'), 'lesson 2 focuses on real Blockly design studio');
assert.equal(lesson2.mode, 'Real Blockly design studio', 'lesson 2 uses real Blockly design studio mode');
assert.equal(lesson2.realBlocklyBuilder, true, 'lesson 2 enables real Blockly workspace');
assert.ok(lesson2.exercises.some(ex => ex.title.includes('Hover')), 'lesson 2 includes hover design exercise');
assert.ok(lesson2.exercises[0].title.includes('מתחילים פשוט'), 'lesson 2 starts simple before adding design blocks');
assert.ok(lesson2.exercises.length >= 9, 'lesson 2 includes the reviewed design flow plus challenge-extension exercises');
assert.ok(lesson2.vocabulary.some(v => v[0] === 'hover'), 'lesson 2 vocabulary includes hover');

const lesson3 = lessons[2];
assert.equal(lesson3.durationMinutes, 170, 'lesson 3 is framed as 170 minutes with deeper code practice');
assert.equal(lesson3.title, 'כפתורים ופעולות קסם עם Blockly', 'lesson 3 title is clear and natural Hebrew');
assert.ok(lesson3.starter.html.includes('onclick="makeHappy()"'), 'lesson 3 has onclick event');
assert.ok(lesson3.starter.js.includes('classList.toggle("magic")'), 'lesson 3 includes classList toggle');
assert.ok(lesson3.exercises.length >= 8, 'lesson 3 includes many exercises');
assert.ok(!lesson3.exercises[0].prompt.includes('הרצה'), 'lesson 3 exercise 1 does not ask for a missing Run button');
assert.ok(lesson3.exercises[0].prompt.includes('כפתור “הפעילו קסם”') && lesson3.exercises[0].prompt.includes('בתצוגה החיה בצד שמאל'), 'lesson 3 exercise 1 points learners to the named live preview button');
assert.equal(lesson3.exercises[0].check.requiresPreviewButtonText, 'הפעילו קסם', 'lesson 3 exercise 1 requires clicking the preview magic button');
assert.ok(!lesson3.exercises[1].prompt.includes('הרצה'), 'lesson 3 exercise 2 does not ask for a missing Run button');
assert.equal(JSON.stringify(lesson3.exercises[1].check.changedBlocklyFields), JSON.stringify([{ type: 'web_button', field: 'LABEL', defaultValue: 'הפעילו קסם' }]), 'lesson 3 exercise 2 now requires changing only the visible button label');
assert.ok(!lesson3.exercises[1].check.unchangedBlocklyFields, 'lesson 3 exercise 2 no longer treats the button as the message-control block');
assert.ok(lesson3.exercises[1].hint.includes('בלוק “כפתור” קובע מה כתוב על הכפתור') && lesson3.exercises[1].hint.includes('בלוק פעולה'), 'lesson 3 exercise 2 explains button label versus click action');
assert.equal(lesson3.exercises[1].check.requiresPreviewButtonClick, true, 'lesson 3 exercise 2 requires trying the renamed preview button');
assert.equal(lesson3.exercises[2].check.requiresCodePeek, true, 'lesson 3 exercise 3 requires opening generated code peek');
assert.equal(lesson3.exercises[2].check.requiresCodeSelectionTab, 'html', 'lesson 3 exercise 3 requires HTML generated-code selection');
assert.deepEqual(Array.from(lesson3.exercises[2].check.requiresCodeSelectionBlockTypes), ['web_button'], 'lesson 3 exercise 3 requires selecting the button block');
assert.ok(lesson3.exercises[2].answerBox?.label.includes('מילת קוד') && lesson3.exercises[2].check.requiresCodeLineAnswer?.requiredSnippets?.includes('button') && lesson3.exercises[2].check.requiresCodeLineAnswer?.requiredSnippets?.includes('id') && lesson3.exercises[2].check.requiresCodeLineAnswer?.requiredSnippets?.includes('onclick'), 'lesson 3 exercise 3 accepts short code words actually visible in the selected HTML button line, including button, id, and onclick');
assert.equal(JSON.stringify(lesson3.exercises[3].check.changedBlocklyFields), JSON.stringify([{ type: 'web_action_message', field: 'TEXT', defaultValue: 'הודעה חדשה מהפעולה ✨' }]), 'lesson 3 exercise 4 requires changing the action-message text, separately from the button label');
assert.ok(lesson3.exercises[3].hint.includes('בלוק פעולה') && lesson3.exercises[3].hint.includes('message.textContent'), 'lesson 3 exercise 4 explains that click-message behavior belongs to the action block');
assert.equal(lesson3.exercises[3].check.requiresPreviewButtonText, 'הפעילו קסם', 'lesson 3 exercise 4 requires pressing the preview button after changing message');
assert.equal(lesson3.exercises[3].check.requiresPreviewMessageChangedFrom, 'כאן תופיע הודעה מהכפתור...', 'lesson 3 exercise 4 requires visible preview message change');
assert.ok(lesson3.exercises[3].check.blockFeedback.includes('חסר בלוק'), 'lesson 3 exercise 4 gives specific missing-action-block feedback');
assert.ok(lesson3.exercises[4].check.changedBlocklyFields?.some(rule => rule.type === 'web_action_emoji' && rule.field === 'EMOJI' && rule.defaultValue === '🤖'), 'lesson 3 exercise 5 requires changing the action emoji from default');
assert.equal(lesson3.exercises[4].check.requiresPreviewEmojiChangedFrom, '✨', 'lesson 3 exercise 5 requires the visible emoji to change in preview');
assert.ok(lesson3.exercises[5].check.changedBlocklyFieldsFromBaseline?.some(rule => rule.type === 'web_action_background' && rule.field === 'BG'), 'lesson 3 exercise 6 requires changing the background action from the entry baseline');
assert.equal(lesson3.exercises[5].check.ensureStarterBlocks?.[0]?.type, 'web_action_background', 'lesson 3 exercise 6 auto-adds the required background action block when missing');
assert.equal(lesson3.exercises[5].check.ensureStarterBlocks?.[0]?.after, 'web_button', 'lesson 3 exercise 6 inserts the background action after the button');
assert.equal(lesson3.exercises[5].check.exactBlockTypeCounts?.web_action_background, 1, 'lesson 3 exercise 6 rejects adding a second background action block');
assert.equal(lesson3.exercises[5].check.requiresPreviewButtonText, 'הפעילו קסם', 'lesson 3 exercise 6 requires pressing the preview button');
assert.equal(lesson3.exercises[6].check.requiresPreviewCardClass, 'magic', 'lesson 3 exercise 7 requires the preview card to enter magic mode');
assert.equal(lesson3.exercises[7].check.requiresCodeSelectionTab, 'js', 'lesson 3 exercise 8 requires selecting generated JavaScript');
assert.ok(lesson3.exercises[7].check.requiresCodeSelectionBlockTypes?.includes('web_action_emoji'), 'lesson 3 exercise 8 requires selecting an action block');
assert.ok(lesson3.exercises.filter(ex => ex.check?.requiresCodeLineAnswer).length <= 1, 'lesson 3 has no duplicate code-word-from-line exercises');
assert.ok(lesson3.exercises[3].check.fieldFeedback.includes('שנו את הטקסט'), 'lesson 3 exercise 4 gives specific unchanged-text feedback');
assert.ok(lessons.find(lesson => lesson.id === 4).exercises[0].check.blockTypes?.includes('lesson_4_title') && lessons.find(lesson => lesson.id === 4).exercises[1].prompt.includes('כותרת/רעיון שבחרתם') && lessons.find(lesson => lesson.id === 4).exercises[2].prompt.includes('כותרת האתר'), 'lesson 4 first asks learners to change the site title, then connects name/topic fields to that chosen project idea');
assert.ok(lesson3.vocabulary.some(v => v[0] === 'onclick'), 'lesson 3 vocabulary includes onclick');

const lessons4to24 = lessons.slice(3, 24);
lessons4to24.forEach(lessonItem => {
  assert.equal(lessonItem.realBlocklyBuilder, true, `lesson ${lessonItem.id} uses real draggable Blockly blocks`);
  assert.equal(lessonItem.blocklyLessonBuilder, true, `lesson ${lessonItem.id} uses the lesson-specific Blockly builder`);
  assert.equal(lessonItem.bridgeBlocks.length, 0, `lesson ${lessonItem.id} does not expose legacy helper/code-card buttons`);
  assert.ok(lessonItem.mode.includes('Real Blockly full rework'), `lesson ${lessonItem.id} is marked as a full real Blockly rework`);
  assert.ok(lessonItem.progressionStage.includes('בלוקים אמיתיים'), `lesson ${lessonItem.id} stays in the block-first phase`);
  assert.ok(lessonItem.blocklyBlocks.length >= 5, `lesson ${lessonItem.id} has several draggable lesson blocks`);
  assert.ok(lessonItem.blocklyBlocks.some(block => block.args0?.length), `lesson ${lessonItem.id} has editable fields/dropdowns inside lesson blocks`);
  if (lessonItem.id >= 13 && lessonItem.id <= 18) {
    assert.ok(lessonItem.exercises.length >= 10, `lesson ${lessonItem.id} has extended code-bridge exercises`);
  } else {
    assert.ok(lessonItem.exercises.length >= (lessonItem.id === 4 ? 11 : [6, 7, 8, 9].includes(lessonItem.id) ? 8 : lessonItem.id === 5 ? 9 : 10), `lesson ${lessonItem.id} has the reviewed exercise count plus challenge extensions`);
  }
  lessonItem.exercises.forEach(ex => {
    const exerciseText = `${ex.title} ${ex.prompt}`;
    assert.ok(exerciseText.includes('בלוק') || exerciseText.includes('תצוגה') || exerciseText.includes('קוד שנוצר') || exerciseText.includes('תיבת הקוד') || exerciseText.includes('HTML') || exerciseText.includes('CSS') || exerciseText.includes('JavaScript') || exerciseText.includes('textContent') || exerciseText.includes('function') || exerciseText.includes('id') || exerciseText.includes('קוד'), `lesson ${lessonItem.id} exercise ${ex.id} is phrased around blocks/preview/generated code/manual code editing`);
    assert.ok(ex.noCheck || (ex.check && Object.keys(ex.check).length > 0), `lesson ${lessonItem.id} exercise ${ex.id} has a validator or is explicitly no-check`);
  });
  assert.ok(!lessonItem.exercises[0].prompt.includes('הריצו'), `lesson ${lessonItem.id} exercise 1 is not a fake run-the-already-running-preview task`);
  assert.ok(lessonItem.exercises[0].check.blockTypes?.length, `lesson ${lessonItem.id} exercise 1 requires a real block action`);
  const blockChecks = lessonItem.exercises.filter(ex => ex.check.blockTypes?.length);
  assert.ok(blockChecks.length >= (lessonItem.id === 4 ? 5 : [6, 7, 8, 9].includes(lessonItem.id) ? 5 : 6), `lesson ${lessonItem.id} requires connected Blockly blocks in most exercises`);
  const final = lessonItem.exercises.at(-1).check;
  if (lessonItem.id !== 4) {
    assert.ok(final.requiresCodePeek || final.changedAny?.length || final.debugCodeIncludes?.length || final.answerIncludes, `lesson ${lessonItem.id} final exercise requires a varied code-understanding task`);
  }
});

